// Parsear arguments de Retell
// Retell envía los args parseados en body.args
// y el string original en body.arguments (dentro del transcript)
const item = items[0].json;
let parsedArgs = {};

// Primero intenta body.args (ya parseado por Retell)
if (item.body.args && typeof item.body.args === 'object' && Object.keys(item.body.args).length > 0) {
  parsedArgs = item.body.args;
}
// Fallback: intenta body.arguments como string
else if (typeof item.body.arguments === 'string') {
  try { parsedArgs = JSON.parse(item.body.arguments); } catch (e) { parsedArgs = {}; }
}
// Fallback: body.arguments como objeto
else if (typeof item.body.arguments === 'object') {
  parsedArgs = item.body.arguments;
}

return [{
  json: {
    ...item,
    body: {
      ...item.body,
      args: parsedArgs
    }
  }
}];

const CONF_ALTA = 0.78;
const CONF_MEDIA = 0.72;
const MAX_PARES = 2;

// Palabras que no discriminan nada en este dominio.
const STOP = new Set([
  'para','como','esta','este','esto','pero','porque','cuando','donde','tengo','puedo','poder',
  'hace','hacer','dice','todo','toda','algo','cosa','favor','gracias','mismo','misma','ahora',
  'entonces','tambien','solo','solamente','desde','hasta','sobre','entre','sino','aunque','cual',
  'quien','muy','mas','menos','nada','nadie','alguien','siempre','nunca','vez','veces','dia','dias',
  'problema','solucion','usuario','usuarios','cliente','tecnocloud','hola','buenas','pues','vale'
]);

function normaliza(s) {
  return String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}
function terminos(s) {
  return normaliza(s).split(/[^a-z0-9]+/).filter((w) => w.length > 3 && !STOP.has(w));
}

// La consulta tal como la formuló el agente de voz.
let consulta = '';
try {
  consulta = $('Parsear Arguments').first().json.body.args.consulta || '';
} catch (e) {
  consulta = '';
}
const consultaTerms = new Set(terminos(consulta));

const rows = $('Buscar en PGVector').all()
  .map((i) => i.json)
  .filter((r) => r && (r.text || r.content));

// Dedup de documentos completos, como antes.
const seen = new Set();
const unique = [];
for (const r of rows) {
  const raw = r.text || r.content || '';
  const key = normaliza(raw).replace(/\s+/g, ' ').trim();
  if (!key || seen.has(key)) continue;
  seen.add(key);
  unique.push(r);
}

if (unique.length === 0) {
  return [{ json: { result: 'no_encontrado', match_count: 0, top_similarity: 0, confidence: 'ninguna' } }];
}

const topSim = Number(unique[0].similarity) || 0;
let confidence = 'baja';
if (topSim >= CONF_ALTA) confidence = 'alta';
else if (topSim >= CONF_MEDIA) confidence = 'media';

// --- troceado en lectura: un par "Problema/Solución" por candidato ---
const candidatos = [];
for (const r of unique) {
  const texto = (r.text || r.content || '').trim();
  const trozos = texto.split(/\n(?=\s*Problema\s*:)/i).map((t) => t.trim()).filter(Boolean);
  for (const t of trozos) {
    const cabecera = t.split(/Soluci[oó]n\s*:/i)[0] || t;
    candidatos.push({
      texto: t,
      propios: new Set(terminos(t)),
      cabecera: new Set(terminos(cabecera)),
      similarity: Number(r.similarity) || 0
    });
  }
}

// Un término que sale en casi todos los pares no discrimina ("colmadwin" cuando todos
// los documentos hablan de Colmadwin). Se pondera por rareza dentro de los candidatos.
const df = new Map();
for (const w of consultaTerms) {
  let n = 0;
  for (const c of candidatos) if (c.propios.has(w)) n += 1;
  df.set(w, n);
}

const pares = candidatos.map((c) => {
  let score = 0;
  for (const w of consultaTerms) {
    const n = df.get(w) || 0;
    if (n === 0 || n === candidatos.length) continue;   // ausente o presente en todos: no informa
    const peso = 1 / n;
    if (c.cabecera.has(w)) score += 2 * peso;
    else if (c.propios.has(w)) score += peso;
  }
  return { texto: c.texto, score, similarity: c.similarity };
});

const conSenal = pares.filter((p) => p.score > 0.6).sort((a, b) => b.score - a.score || b.similarity - a.similarity);

let contenido;
let seleccionados;
if (consultaTerms.size > 0 && conSenal.length > 0) {
  seleccionados = conSenal.slice(0, MAX_PARES);
  contenido = seleccionados.map((p) => p.texto).join('\n\n');
} else {
  // Sin señal suficiente para elegir: se devuelve lo de siempre, sin empeorar nada.
  seleccionados = pares;
  contenido = unique.map((r) => (r.text || r.content || '').trim()).filter(Boolean).join('\n\n');
}

return [{
  json: {
    result: contenido,
    match_count: seleccionados.length,
    top_similarity: Number(topSim.toFixed(4)),
    confidence,
    pares_totales: pares.length,
    pares_devueltos: seleccionados.length
  }
}];

// Compone el aviso a soporte a partir del resumen de IA, con degradado explícito si falla.
const base = $('Preparar Registro').first().json;

const nombre = base.nombre;
const telefono = base.telefono;
const resuelto = base.resuelto;
const urgente = base.urgente;

function recortar(txt, max) {
  const limpio = String(txt || '').replace(/\s+/g, ' ').trim();
  if (limpio.length <= max) return limpio.replace(/[\s:;,\-–—]+$/, '');
  const corte = limpio.slice(0, max);
  const ultimoEspacio = corte.lastIndexOf(' ');
  const base2 = ultimoEspacio > 20 ? corte.slice(0, ultimoEspacio) : corte;
  return base2.replace(/[\s:;,\-–—]+$/, '') + '...';
}

let intencionCorta = '';
let intencion = '';
let categoria = '';
let personaSolicitada = '';
let resumenIaOk = false;

try {
  const resp = $('Generar Resumen IA').first().json;
  const contenido = resp.choices[0].message.content;
  const parsed = JSON.parse(contenido);
  intencionCorta = String(parsed.intencion_corta || '').trim();
  intencion = String(parsed.intencion_larga || '').trim();
  categoria = String(parsed.categoria || '').trim();
  personaSolicitada = String(parsed.persona_solicitada || '').trim();
  if (!intencionCorta || !intencion) throw new Error('resumen incompleto');
  resumenIaOk = true;
} catch (e) {
  resumenIaOk = false;
}

if (!resumenIaOk) {
  // Degradado: lo que dictó Laura, pero sin cortar a media frase.
  intencion = base.intencionTool || 'Sin resumen disponible (fallo al generar el resumen).';
  intencionCorta = recortar(base.intencionTool || 'Llamada de soporte', 80);
  categoria = '';
}
intencionCorta = recortar(intencionCorta, 110);

// Lo que dijo el cliente manda sobre lo que deduzca el resumen.
if (base.aplicacion) categoria = base.aplicacion;
if (base.personaSolicitada) personaSolicitada = base.personaSolicitada;

const pillResuelto = resuelto === 'si'
  ? '<span style="display:inline-block;background:#e6f4ea;color:#1e7e34;padding:6px 18px;border-radius:20px;font-size:13px;font-weight:700;letter-spacing:0.5px;">RESUELTO</span>'
  : '<span style="display:inline-block;background:#fdecea;color:#c0392b;padding:6px 18px;border-radius:20px;font-size:13px;font-weight:700;letter-spacing:0.5px;">NO RESUELTO</span>';

const pillUrgente = urgente === 'si'
  ? ' <span style="display:inline-block;background:#fff3e0;color:#e65100;padding:6px 18px;border-radius:20px;font-size:13px;font-weight:700;letter-spacing:0.5px;margin-left:8px;">URGENTE</span>'
  : '';

const pillReclama = base.yaReclamado === 'si'
  ? ' <span style="display:inline-block;background:#fff3e0;color:#b03a00;padding:6px 18px;border-radius:20px;font-size:13px;font-weight:700;letter-spacing:0.5px;margin-left:8px;">YA HABÍA RECLAMADO</span>'
  : '';

const pillHtml = pillResuelto + pillUrgente + pillReclama;

const prefijo = urgente === 'si' ? 'Incidencia urgente' : 'Incidencia';
const etiquetas = [];
if (categoria) etiquetas.push(categoria);
if (base.yaReclamado === 'si') etiquetas.push('reclama');
const etiquetaCategoria = etiquetas.length ? ' [' + etiquetas.join(' · ') + ']' : '';
const emailSubject = prefijo + etiquetaCategoria + ' - ' + nombre + ' - ' + intencionCorta;

// Cola del cuerpo: datos que soporte necesita y antes no llegaban.
const extras = [];
if (categoria) extras.push('Aplicación o servicio: ' + categoria);
if (base.telefonoAlternativo) extras.push('Teléfono alternativo facilitado: ' + base.telefonoAlternativo);
if (personaSolicitada) extras.push('Pide hablar con: ' + personaSolicitada);
if (base.yaReclamado === 'si') extras.push('El cliente dice que ya había contactado antes y sigue esperando.');
if (!resumenIaOk) extras.push('Aviso: el resumen automático falló; este texto es el que dictó el agente de voz.');
const intencionFinal = extras.length ? intencion + '\n\n' + extras.join('\n') : intencion;

return [{
  json: {
    Timestamp: new Date().toLocaleString('es-ES', { timeZone: 'Europe/Madrid' }),
    Nombre: nombre,
    Telefono: telefono,
    Intencion: intencionFinal,
    IntencionCorta: intencionCorta,
    Categoria: categoria,
    PersonaSolicitada: personaSolicitada,
    YaReclamado: base.yaReclamado,
    Resuelto: resuelto,
    Urgente: urgente,
    pillHtml: pillHtml,
    emailSubject: emailSubject,
    resumenIaOk: resumenIaOk,
    callId: base.callId
  }
}];

// Prepara el registro de la llamada: normaliza los datos que dicta Laura y detecta reenvíos.
const body = $('Parsear Arguments').first().json.body || {};
const args = body.args || {};
const call = body.call || {};

const callId = call.call_id || body.call_id || '';
const transcript = call.transcript || '';

// --- Nombre: marcador explícito en vez de dejarlo vacío ---
const nombreBruto = String(args.nombre_cliente || '').trim();
const nombre = nombreBruto.length > 1 ? nombreBruto : 'No facilitado';

// --- Teléfono: Laura a veces lo dicta en palabras ("seis dos nueve - ocho...") ---
const PALABRAS = {
  cero: '0', uno: '1', un: '1', una: '1', dos: '2', tres: '3', cuatro: '4',
  cinco: '5', seis: '6', siete: '7', ocho: '8', nueve: '9'
};
function aDigitos(txt) {
  return String(txt || '')
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .split(/[^a-z0-9+]+/)
    .map((t) => (PALABRAS[t] !== undefined ? PALABRAS[t] : t))
    .join('');
}
function normalizarTelefono(txt) {
  const s = aDigitos(txt);
  let d = s.replace(/\D/g, '');
  if (d.startsWith('0034')) d = d.slice(4);
  else if (d.startsWith('34') && d.length > 9) d = d.slice(2);
  if (d.length !== 9) return '';
  if (!/^[6789]/.test(d)) return '';
  return '+34' + d;
}

const telOrigen = normalizarTelefono(call.from_number) || String(call.from_number || '');
const telAlt = normalizarTelefono(args.telefono_cliente);
const telefono = telAlt || telOrigen || 'No facilitado';
const telefonoAlternativo = telAlt && telAlt !== telOrigen ? telAlt : '';

const resuelto = String(args.resuelto || 'no').toLowerCase().startsWith('s') ? 'si' : 'no';
const urgente = String(args.urgente || 'no').toLowerCase().startsWith('s') ? 'si' : 'no';
const yaReclamado = String(args.ya_reclamado || 'no').toLowerCase().startsWith('s') ? 'si' : 'no';
const intencionTool = String(args.intencion || '').trim();

// Campos que Laura empieza a mandar con las tools v42. Los marcadores acordados
// ('No identificada', 'Ninguna') se traducen a vacío para no ensuciar el aviso.
function sinMarcador(valor, marcadores) {
  const v = String(valor || '').trim();
  if (!v) return '';
  const plano = v.toLowerCase();
  return marcadores.some((m) => plano === m) ? '' : v;
}
const aplicacion = sinMarcador(args.aplicacion, ['no identificada', 'no identificado', 'ninguna', 'no aplica']);
const personaSolicitada = sinMarcador(args.persona_solicitada, ['ninguna', 'ninguno', 'nadie', 'no']);

// --- Idempotencia: la reserva atómica la hace el nodo Postgres siguiente ---
// Se sanea porque el id se interpola en SQL (sentencias múltiples no admiten parámetros).
const callIdSeguro = (callId || ('sin-call-id-' + Date.now()))
  .replace(/[^A-Za-z0-9_-]/g, '')
  .slice(0, 80) || ('sin-call-id-' + Date.now());

// --- Prompt del resumen: se construye aquí para que el nodo HTTP quede limpio ---
const promptResumen = [
  'Eres asistente de soporte tecnico de Tecnocloud. Lee la conversacion entre Laura (agente de voz) y el cliente',
  'y devuelve un JSON estricto con el resumen para el aviso interno de soporte.',
  '',
  'Reglas:',
  '- NO inventes nada. Si un dato no aparece en la conversacion, omitelo.',
  '- Cita literalmente mensajes de error, nombres de usuario, URLs, rutas, equipos y horarios que dijo el cliente.',
  '- Espanol de Espana, frases completas, sin vinetas y sin markdown.',
  '',
  'Devuelve solo este JSON:',
  '{',
  '  "intencion_corta": "de 4 a 14 palabras describiendo el problema o la peticion, sin punto final",',
  '  "intencion_larga": "de 4 a 8 frases que incluyan, cuando existan: motivo y aplicacion implicada; datos concretos citados por el cliente (error literal, usuario, URL, ruta, equipo, horario); si pide hablar con una persona (Silvia, Dani, Carlos), el motivo concreto que dio; los pasos que Laura le pidio probar y el resultado de cada uno; y el estado final (resuelto, escalado al equipo, derivado a comercial o pendiente de devolver llamada)",',
  '  "categoria": "una sola de estas: Gesfincas, Colmadwin, Editor.net, Outlook, Office 365, Teams, OneDrive, SharePoint, Aplifisa, Classic Conta, Gotelgest, Siltra, Autofirma, Escritorio remoto, Contrasena, Copias de seguridad, Correo, Impresora, Red, Comercial, Hablar con persona, Otros",',
  '  "persona_solicitada": "Silvia, Dani, Carlos o cadena vacia si no pidio hablar con nadie en concreto"',
  '}',
  '',
  'Datos que Laura envio en la tool (pueden estar incompletos o mal transcritos):',
  JSON.stringify({ nombre_cliente: args.nombre_cliente, telefono_cliente: args.telefono_cliente, aplicacion: aplicacion, persona_solicitada: personaSolicitada, intencion: intencionTool, ya_reclamado: yaReclamado, resuelto: resuelto, urgente: urgente }),
  '',
  'Conversacion completa:',
  transcript || '(sin transcripcion disponible)'
].join('\n');

return [{
  json: {
    callId,
    callIdSeguro,
    nombre,
    telefono,
    telefonoAlternativo,
    telefonoOrigen: telOrigen,
    aplicacion,
    personaSolicitada,
    yaReclamado,
    resuelto,
    urgente,
    intencionTool,
    transcript,
    promptResumen
  }
}];

// Verifica que el aviso llegó de verdad. Si algo falló, lanza error para que el
// Error Handler del workflow lo publique en Slack #01-incidencias en vez de morir en el log.
function salida(nombreNodo) {
  try {
    return $(nombreNodo).first().json;
  } catch (e) {
    return null;
  }
}

const base = $('Preparar Registro').first().json;
const compuesto = $('Registrar Llamada').first().json;
const fallos = [];

const resumen = salida('Generar Resumen IA');
if (!resumen || resumen.error || !resumen.choices) fallos.push('resumen automático con IA');

const mail = salida('Send a message');
if (!mail || mail.error) fallos.push('email a incidencias@tecnocloud.es');

const hoja = salida('Registrar en Google Sheets');
if (!hoja || hoja.error) fallos.push('fila en el Google Sheet de registro');

if (fallos.length) {
  throw new Error(
    'Registro de llamada incompleto (call_id ' + (base.callId || 'desconocido') +
    ', cliente ' + base.nombre + '): falló ' + fallos.join(' y ') +
    '. Revisar si soporte se ha quedado sin el aviso.'
  );
}

return [{ json: { ok: true, callId: base.callId, nombre: base.nombre, resumenIaOk: compuesto.resumenIaOk } }];

