CREATE TABLE IF NOT EXISTS retell_llamadas_registradas (
  call_id text PRIMARY KEY,
  registrada_en timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS retell_llamadas_registradas_fecha_idx
  ON retell_llamadas_registradas (registrada_en);
DELETE FROM retell_llamadas_registradas WHERE registrada_en < now() - interval '30 days';
WITH reserva AS (
  INSERT INTO retell_llamadas_registradas (call_id)
  VALUES ('{{ $json.callIdSeguro }}')
  ON CONFLICT (call_id) DO NOTHING
  RETURNING call_id
)
SELECT CASE WHEN EXISTS (SELECT 1 FROM reserva) THEN 'nueva' ELSE 'duplicada' END AS estado;
